import{z as n,x as B,o as e,c as p,q as i,j as o,D as E,d as A,s as r,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"MPC 应用","description":"","frontmatter":{"title":"MPC 应用","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mpc-applications.md","filePath":"cs/mpc-applications.md","lastUpdated":1791063341000}'),d={name:"cs/mpc-applications.md"};function c(m,a,h,C,P,D){const s=B("Mermaid");return e(),p("div",null,[a[2]||(a[2]=i('<h1 id="mpc-应用" tabindex="-1">MPC 应用 <a class="header-anchor" href="#mpc-应用" aria-label="Permalink to &quot;MPC 应用&quot;">​</a></h1><div class="epigraph"><p>多方计算让机构在不交出明文表的前提下算交集或统计。应用落点是反洗钱式的集合交集、联合分析；成本在通信轮次与恶意模型。</p><footer>—— 据 Yao；PSI 工程实践点名；对照[门限与 MPC 直觉](/cs/threshold-mpc)</footer></div><p>上一课<a href="/cs/data-masking-tokenization">令牌化</a>仍有保险库存明文；缺口是更进一步——<strong>计算时也不把表集中到任何一方</strong>。密码学单元已讲过 MPC 直觉；本课收应用与限制。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两家银行想比对客户重叠、几家机构想做联合统计，但明文交换违法或违约。PSI（隐私集合求交）与 MPC 让协议在密文份额上运算，最后只打开约定的输出。缺口是三件：多数协议只假设半诚实而非任意叛徒、性能比明文慢几个数量级、以及输出本身会泄漏。</p><p><span class="marginnote">PSI（隐私集合求交）就是「双方各自拿着一份名单，算出共同部分，且谁也看不到对方名单上不在交集里的名字」。它是 MPC 思想收窄到一个具体函数的量产版——函数越具体，协议越能压到工程可用。</span></p><h3 id="输出仍可能漏" tabindex="-1">输出仍可能漏 <a class="header-anchor" href="#输出仍可能漏" aria-label="Permalink to &quot;输出仍可能漏&quot;">​</a></h3><p>输出仍可能漏：交集本身是信息——「某人同时在两家名单里」常常就是结论。要压这个泄漏，可以在输出上再叠差分隐私噪声。</p><p><span class="marginnote">为什么「只输出交集」也可能闯祸：如果 B 银行的名单只有三个人，那么「你的客户张三与我们有交集」这句话等于泄露了 B 名单的三分之一内容。交集越小、越结构化，单条输出携带的关于输入的信息就越多——协议保密不等于结论保密。</span></p><p><span class="marginnote">Yao；PSI 文献。PIR 下一课是检索隐私。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法先对照令牌化的中心化保险库：令牌化把明文锁进一家，MPC 干脆让明文不出现。应用清单按成熟度排：PSI 已是反洗钱与通讯录发现里的量产技术；联合统计（均值、直方图）次之；通用两方计算仍然贵。下一课 PIR。</p>',13)),(e(),o(l,null,{default:E(()=>[r(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%A7%81%E6%9C%89%E8%A1%A8%22%5D%20--%3E%20MPC%5B%22%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20B%5B%22%E7%A7%81%E6%9C%89%E8%A1%A8%22%5D%20--%3E%20MPC%0A%20%20MPC%20--%3E%20Y%5B%22%E5%8F%AA%E6%89%93%E5%BC%80%E7%BA%A6%E5%AE%9A%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[A("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"机制落点是治理语义变了：「数据不出域」从管理承诺变成协议性质——各方只学到函数输出，学不到对方输入的其余部分，审计对象从数据流转变成协议与实现的正确性。代价同样实在：通信轮次随电路深度增长，换成恶意模型还要给每个份额加可验证性，开销再涨一截。PIR 下一课是用户对数据库的隐私查询。",-1)),(e(),o(l,null,{default:E(()=>[r(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%7B%22%E5%A8%81%E8%83%81%E6%A8%A1%E5%9E%8B%E6%98%AF%E5%93%AA%E7%A7%8D%3F%22%7D%0A%20%20M%20--%3E%7C%22%E5%8D%8A%E8%AF%9A%E5%AE%9E%22%7C%20SH%5B%22%E4%BC%9A%E8%80%81%E8%80%81%E5%AE%9E%E5%AE%9E%E8%B7%91%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20SH%20--%3E%20SH2%5B%22%E4%BD%86%E5%81%B7%E7%9C%8B%E4%B8%AD%E9%97%B4%E6%B6%88%E6%81%AF%E6%8E%A8%E7%90%86%E8%BE%93%E5%85%A5%22%5D%0A%20%20SH2%20--%3E%20SH3%5B%22%E5%8D%8F%E8%AE%AE%E5%8F%AA%E9%9C%80%E6%8E%A9%E7%9B%96%E6%B6%88%E6%81%AF%3A%20%E7%9B%B8%E5%AF%B9%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20M%20--%3E%7C%22%E6%81%B6%E6%84%8F%22%7C%20MA%5B%22%E5%8F%AF%E8%83%BD%E5%81%8F%E7%A6%BB%E5%8D%8F%E8%AE%AE%E4%BB%BB%E6%84%8F%E4%BD%9C%E5%BC%8A%22%5D%0A%20%20MA%20--%3E%20MA2%5B%22%E6%AF%8F%E4%B8%AA%E4%BB%BD%E9%A2%9D%E8%A6%81%E5%B8%A6%E5%8F%AF%E9%AA%8C%E8%AF%81%E6%80%A7%E8%AF%81%E6%98%8E%22%5D%0A%20%20MA2%20--%3E%20MA3%5B%22%E8%BD%AE%E6%AC%A1%E4%B8%8E%E5%B8%A6%E5%AE%BD%E5%86%8D%E6%B6%A8%E4%B8%80%E6%88%AA%22%5D%0A%20%20SH3%20--%3E%20OUT%5B%22%E5%90%8C%E4%B8%80%E5%A5%97%E5%BA%94%E7%94%A8%3A%20%E6%8D%A2%E5%81%87%E8%AE%BE%3D%E6%8D%A2%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20MA3%20--%3E%20OUT%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">半诚实（semi-honest）对手的准确定位是「好奇但守规矩」：它严格按协议执行、一步不偏离，只是把过程中看到的消息全部记下来尝试反推输入。恶意（malicious）对手则连规矩都不守，所以协议必须自带「抓作弊」的证据机制——贵就贵在这里。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把 MPC 写成量化交易的部署方案；边界要点名：参与方串通超过阈值、输入长度这类元数据侧信道、协议实现错误，都不被理论安全覆盖。PIR 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>令牌化仍有库；MPC 让计算分散。</li><li>输出策略与模型假设决定泄漏。</li><li>应用是交集与统计，不是万能。</li><li>下一课 PIR。</li><li>出处：Yao；对照 <a href="/cs/threshold-mpc">threshold-mpc</a>。</li></ul>',5))])}const f=n(d,[["render",c]]);export{_ as __pageData,f as default};
